// ========== CONFIGURACIÓN ==========
const ASESORES_EXCLUIDOS = [12, 27]; // IDs de asesores a excluir
// ===================================

// Obtener todos los items del input
const allItems = $input.all();

// Filtrar y limpiar items
const itemsValidos = [];
const horariosVistos = new Set();

for (const item of allItems) {
  // Saltar si el objeto está vacío o no tiene la estructura esperada
  if (!item.json || !item.json.start || !item.json.asesor) {
    continue;
  }

  // Filtrar asesores excluidos
  if (ASESORES_EXCLUIDOS.includes(item.json.asesor)) {
    continue;
  }

  // Verificar si es sábado (6) o domingo (0)
  const fecha = new Date(item.json.start);
  const diaSemana = fecha.getDay();

  if (diaSemana === 0 || diaSemana === 6) {
    continue; // Saltar sábados y domingos
  }

  // Verificar si ya existe un turno con este horario (sin importar el asesor)
  const horario = item.json.start;

  if (!horariosVistos.has(horario)) {
    horariosVistos.add(horario);
    itemsValidos.push(item);
  }
}

// Ordenar por fecha y hora (del más antiguo al más reciente)
itemsValidos.sort((a, b) => {
  const fechaA = new Date(a.json.start);
  const fechaB = new Date(b.json.start);
  return fechaA - fechaB;
});

return itemsValidos;

// ========== CONFIGURACIÓN ==========
const MINUTOS_ENTRE_TURNOS = 20;   // Duración de cada turno
const HORARIO_INICIO = 8;          // Hora de inicio (8 = 08:00)
const HORARIO_FIN = 11;            // Hora de fin (11 = 11:00)
const TURNOS_TOTALES = 6;          // Cantidad total de turnos a generar
// ===================================

// Obtener TODOS los items que vienen del HTTP Request (turnos ocupados)
const allItems = $('HTTP Request3').all();
const asesorId = $('Loop Over Items').item.json.id;

// Extraer fechas únicas de los turnos ocupados
const fechasUnicas = [...new Set(allItems.map(item => item.json.start.split(' ')[0]))];

// Función para generar turnos de un día
function generarTurnosDelDia(fecha) {
  const turnos = [];
  const [year, month, day] = fecha.split('-');

  let hora = HORARIO_INICIO;
  let minuto = 0;

  // Generar turnos solo dentro del rango definido
  while (hora < HORARIO_FIN) {
    const horaStr = hora.toString().padStart(2, '0');
    const minutoStr = minuto.toString().padStart(2, '0');
    turnos.push(`${year}-${month}-${day} ${horaStr}:${minutoStr}:00`);

    minuto += MINUTOS_ENTRE_TURNOS;
    if (minuto >= 60) {
      minuto -= 60;
      hora += 1;
    }
  }

  return turnos;
}

// Función para verificar si un turno está disponible
function estaDisponible(turno, turnosOcupados) {
  const turnoTime = new Date(turno).getTime();

  return !turnosOcupados.some(ocupado => {
    const ocupadoTime = new Date(ocupado).getTime();
    const diferenciaMinutos = Math.abs(turnoTime - ocupadoTime) / (1000 * 60);
    return diferenciaMinutos < MINUTOS_ENTRE_TURNOS;
  });
}

// Función para extraer la hora de un turno (formato: "HH:mm")
function obtenerHora(turno) {
  return turno.split(' ')[1].substring(0, 5);
}

// Obtener todos los turnos ocupados
const turnosOcupados = allItems.map(item => item.json.start);

// Generar TODOS los turnos disponibles de TODAS las fechas
const todosLosDisponibles = [];

fechasUnicas.forEach(fecha => {
  const todosTurnos = generarTurnosDelDia(fecha);

  todosTurnos.forEach(turno => {
    if (estaDisponible(turno, turnosOcupados)) {
      todosLosDisponibles.push(turno);
    }
  });
});

// Seleccionar turnos priorizando diversidad de días y horarios
const turnosSeleccionados = [];
const diasUsados = new Set();
const horariosUsados = new Set();

// Mezclar los turnos disponibles
const turnosAleatorios = todosLosDisponibles.sort(() => Math.random() - 0.5);

// Intentar seleccionar turnos con máxima diversidad
for (let turno of turnosAleatorios) {
  if (turnosSeleccionados.length >= TURNOS_TOTALES) break;

  const fecha = turno.split(' ')[0];
  const hora = obtenerHora(turno);

  // Priorizar turnos de días y horarios diferentes
  if (!diasUsados.has(fecha) || !horariosUsados.has(hora)) {
    turnosSeleccionados.push(turno);
    diasUsados.add(fecha);
    horariosUsados.add(hora);
  }
}

// Si aún faltan turnos y no se pudo lograr máxima diversidad, completar con cualquier disponible
if (turnosSeleccionados.length < TURNOS_TOTALES) {
  for (let turno of turnosAleatorios) {
    if (turnosSeleccionados.length >= TURNOS_TOTALES) break;
    if (!turnosSeleccionados.includes(turno)) {
      turnosSeleccionados.push(turno);
    }
  }
}

// Formatear la salida
const resultado = turnosSeleccionados.map(turno => {
  const dateKey = 'key_' + turno.replace(/[-:\s]/g, '');

  return {
    json: {
      start: turno,
      className: "available",
      dateKey: dateKey,
      asesor: asesorId
    }
  };
});

return resultado;

